        # Create an NFS snapshot for the specified volume
        if not self.nfs_client:
            raise Exception("NFS client is not connected")
        return self.nfs_client.create_snapshot(volume_id)

    def restore_snapshot(self, volume_id, snapshot_id):
        # Restore the specified snapshot to the volume
        if not self.nfs_client:
            raise Exception("NFS client is not connected")
        return self.nfs_client.restore_snapshot(volume_id, snapshot_id)

    def delete_snapshot(self, snapshot_id):
        # Delete the specified snapshot
        if not self.nfs_client:
            raise Exception("NFS client is not connected")
        return self.nfs_client.delete_snapshot(snapshot_id)
