static QString warnIfUnrecognizedIniSection(const QStringList &recognizedIniSections,
                                          const QString &iniPath, const QString &key)
{
    const auto index = key.indexOf(u'/');
    if (index == -1)
        return {};

    const auto &section = key.left(index);
    if (recognizedIniSections.contains(section))
        return {};

    return "Unrecognized section \"%1\" in %2\n"_L1.arg(section).arg(iniPath)
            + "Recognized sections are: ["_L1 + recognizedIniSections.join(", "_L1) + u']';
}
